BEGIN;
SELECT plan(30);
SELECT has_table('public','shipping_settings','shipping settings table exists');
SELECT has_table('public','shipping_providers','shipping providers table exists');
SELECT has_table('public','shipping_quote_cache','shipping cache table exists');
SELECT has_table('public','shipping_rules','shipping rules table exists');
SELECT has_table('public','shipping_audit_logs','shipping audit table exists');
SELECT has_table('public','shipping_quote_rate_limits','shipping quote rate-limit table exists');
SELECT has_column('public','products','weight_kg','products support shipping weight');
SELECT has_column('public','products','requires_shipping','products can opt out of shipping');
SELECT has_column('public','shipping_settings','store_key','shipping settings are tenant-scoped');
SELECT has_column('public','shipping_providers','store_key','shipping providers are tenant-scoped');
SELECT has_column('public','shipping_quote_cache','store_key','shipping cache is tenant-scoped');
SELECT has_column('public','shipping_rules','store_key','shipping rules are tenant-scoped');
SELECT has_column('public','shipping_audit_logs','store_key','shipping audit is tenant-scoped');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_settings'::regclass),'settings RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_providers'::regclass),'providers RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_quote_cache'::regclass),'cache RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_rules'::regclass),'rules RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_audit_logs'::regclass),'audit RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.shipping_quote_rate_limits'::regclass),'rate-limit RLS enabled');
SELECT ok(NOT has_table_privilege('anon','public.shipping_settings','SELECT'),'anonymous users cannot read shipping settings');
SELECT ok(NOT has_table_privilege('anon','public.shipping_providers','SELECT'),'anonymous users cannot read provider credentials');
SELECT ok(NOT has_table_privilege('authenticated','public.shipping_providers','SELECT'),'authenticated users cannot read provider credentials directly');
SELECT ok(NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='shipping_providers' AND policyname='shipping_providers_admin_select'),'provider credentials have no client-side SELECT policy');
SELECT ok(NOT has_table_privilege('anon','public.shipping_audit_logs','SELECT'),'anonymous users cannot read shipping audit');
SELECT ok(NOT has_table_privilege('anon','public.shipping_quote_cache','SELECT'),'anonymous users cannot read shipping cache');
SELECT ok(to_regprocedure('public.consume_shipping_quote_rate_limit(text,timestamptz,integer)') IS NOT NULL,'server-side quote rate limiter exists');
SELECT ok((SELECT count(*)=1 FROM public.shipping_settings WHERE store_key='papelemi' AND singleton=true),'PapeLemi has one default shipping settings row');
SELECT ok(NOT has_table_privilege('anon','public.shipping_quote_rate_limits','SELECT'),'anonymous users cannot access shipping rate-limit buckets');
SELECT ok(EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='shipping_settings' AND policyname='shipping_settings_admin_select' AND qual ILIKE '%papelemi%'),'shipping settings policy is scoped to PapeLemi');
SELECT ok(NOT has_function_privilege('anon','public.consume_shipping_quote_rate_limit(text,timestamptz,integer)','EXECUTE'),'anonymous users cannot execute the quote rate limiter');
SELECT * FROM finish();
ROLLBACK;
